    modes.squash.v=clamp(modes.squash.v-(kind==='shake'?2.6:3.5)*strength,-8,8);
    modes.ripple.v=clamp(modes.ripple.v+(kind==='shake'?5:3.5)*strength,-8,8);
    modes.dent.v=clamp(modes.dent.v+(kind==='shake'?0:4.8)*strength,-8,8);
